-- calc_customers_is_approved
-- Field: Customers.IsApproved
-- Type: calculated | DataType: boolean | Returns: BOOLEAN

CREATE OR REPLACE FUNCTION calc_customers_is_approved(p_customer_id TEXT)
RETURNS BOOLEAN AS $$
  SELECT (CASE WHEN COALESCE((SELECT NULLIF(current_color, '') FROM customers WHERE customer_id = p_customer_id), '') = 'Green' THEN TRUE ELSE FALSE END)::boolean;
$$ LANGUAGE sql STABLE;

